package com.remoteoffice.auth.controller;

import com.remoteoffice.auth.dto.ClientDeviceMetadata;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.session.FindByIndexNameSessionRepository;
import org.springframework.session.Session;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth/active-sessions")
public class SessionMetadataController {

    private final FindByIndexNameSessionRepository<? extends Session> sessionRepository;

    public SessionMetadataController(FindByIndexNameSessionRepository<? extends Session> sessionRepository) {
        this.sessionRepository = sessionRepository;
    }

    @GetMapping("/{sessionId}/device-info")
    public ResponseEntity<ClientDeviceMetadata> getSessionDeviceMetadata(
            @PathVariable String sessionId,
            Authentication authentication) {
        Session session = sessionRepository.findById(sessionId);
        if (session == null) {
            return ResponseEntity.notFound().build();
        }
        String sessionUser = session.getAttribute(FindByIndexNameSessionRepository.PRINCIPAL_NAME_INDEX_NAME);
        if (sessionUser == null || !sessionUser.equals(authentication.getName())) {
            throw new AccessDeniedException("Access to device telemetry of another user's session is forbidden");
        }
        ClientDeviceMetadata metadata = new ClientDeviceMetadata(
                session.getAttribute("remoteIp"),
                session.getAttribute("userAgent"),
                session.getAttribute("geoCity"),
                session.getLastAccessedTime()
        );
        return ResponseEntity.ok(metadata);
    }
}
